// count empty cells reachable from (sx, sy), capped so we stay in budget
function reach(grid, w, h, sx, sy, limit) {
  const seen = {};
  const queue = [[sx, sy]];
  seen[sx + "," + sy] = true;
  let count = 0;
  let qi = 0;
  while (qi < queue.length && count < limit) {
    const cur = queue[qi++];
    count++;
    for (const k in DIRS) {
      const nx = cur[0] + DIRS[k][0];
      const ny = cur[1] + DIRS[k][1];
      const key = nx + "," + ny;
      if (open(grid, w, h, nx, ny) && !seen[key]) {
        seen[key] = true;
        queue.push([nx, ny]);
      }
    }
  }
  return count;
}

